using System.Reflection;
using McpServer.Support.Mcp.Tests.Infrastructure;

namespace McpServer.Support.Mcp.Tests.Documentation;

/// <summary>Serializes repository-root tests that temporarily mutate process-wide state.</summary>
[CollectionDefinition(Name, DisableParallelization = true)]
public sealed class RepositoryRootProcessStateCollection
{
    /// <summary>Collection name for external-artifact repository-root tests.</summary>
    public const string Name = "Repository root process state";
}

/// <summary>
/// TEST-MCP-USECASE-018: Fourteenth-review external-artifact repository-root regressions.
/// </summary>
[Collection(RepositoryRootProcessStateCollection.Name)]
public sealed class BugTriage139FourteenthHarnessTests
{
    /// <summary>
    /// A consumer launched from its true external output directory resolves the checkout without an
    /// environment override.
    /// </summary>
    [Fact]
    public void RepositoryRoot_ExternalBinaryDirectoryWithoutOverride_ResolvesCheckout()
    {
        var previousRoot = Environment.GetEnvironmentVariable("MCP_REPOSITORY_ROOT");
        var previousDirectory = Environment.CurrentDirectory;
        try
        {
            Environment.SetEnvironmentVariable("MCP_REPOSITORY_ROOT", null);
            Environment.CurrentDirectory = AppContext.BaseDirectory;

            var actual = RepositoryEvidenceTestSupport.ResolveRepositoryRoot();

            Assert.Equal(SourceRepositoryRoot(), actual);
        }
        finally
        {
            Environment.CurrentDirectory = previousDirectory;
            Environment.SetEnvironmentVariable("MCP_REPOSITORY_ROOT", previousRoot);
        }
    }

    /// <summary>
    /// The built test assembly contains exactly the native cases for its current platform and no
    /// unsupported platform cases, so discovery cannot turn an unsupported source branch into a pass.
    /// </summary>
    [Fact]
    public void PlatformNativeTests_AreCompiledAndDiscoverableOnlyForCurrentPlatform()
    {
        Assert.True(
            OperatingSystem.IsWindows() || OperatingSystem.IsLinux(),
            "The native BUG-TRIAGE-139 inventory supports Windows and Linux only.");

        var windowsInventory = new Dictionary<string, int>(StringComparer.Ordinal)
        {
            ["McpServer.Support.Mcp.Tests.Storage.BugTriage139FifteenthWindowsNativeTests"] = 3,
            ["McpServer.Support.Mcp.Tests.Storage.BugTriage139SixteenthIdentityWindowsTests"] = 3,
            ["McpServer.Support.Mcp.Tests.Documentation.BugTriage139SixteenthWindowsProcessTests"] = 3,
        };
        var linuxInventory = new Dictionary<string, int>(StringComparer.Ordinal)
        {
            ["McpServer.Support.Mcp.Tests.Storage.BugTriage139FifteenthLinuxNativeTests"] = 3,
            ["McpServer.Support.Mcp.Tests.Storage.BugTriage139SixteenthLinuxTests"] = 7,
            ["McpServer.Support.Mcp.Tests.Services.RequirementsFourteenthLinuxNativeTests"] = 1,
        };
        var applicableInventory = OperatingSystem.IsWindows()
            ? windowsInventory
            : linuxInventory;
        var unsupportedInventory = OperatingSystem.IsWindows()
            ? linuxInventory
            : windowsInventory;
        var assembly = typeof(BugTriage139FourteenthHarnessTests).Assembly;

        foreach (var expected in applicableInventory)
        {
            var type = assembly.GetType(expected.Key, throwOnError: false);
            Assert.NotNull(type);
            var discoveredFacts = type!.GetMethods(
                    BindingFlags.Instance | BindingFlags.Public | BindingFlags.DeclaredOnly)
                .Count(method => method.GetCustomAttributesData().Any(
                    attribute => string.Equals(
                        attribute.AttributeType.FullName,
                        "Xunit.FactAttribute",
                        StringComparison.Ordinal)));
            Assert.Equal(expected.Value, discoveredFacts);
        }

        Assert.All(
            unsupportedInventory.Keys,
            typeName => Assert.Null(assembly.GetType(typeName, throwOnError: false)));
        Assert.Equal(
            OperatingSystem.IsWindows() ? 9 : 11,
            applicableInventory.Values.Sum());
    }

    /// <summary>
    /// A descendant that inherits redirected pipes cannot outlive the bounded process operation
    /// after its direct parent exits.
    /// </summary>
    [Fact]
    public void ProcessRunner_ExitedParentWithPipeHoldingDescendant_KillsTreeWithinBound()
    {
        string executable;
        IReadOnlyList<string> arguments;
        if (OperatingSystem.IsWindows())
        {
            executable = "pwsh.exe";
            var parentScript = string.Join(
                "; ",
                "$start = [Diagnostics.ProcessStartInfo]::new()",
                "$start.FileName = 'pwsh.exe'",
                "$start.UseShellExecute = $false",
                "$start.ArgumentList.Add('-NoProfile')",
                "$start.ArgumentList.Add('-NonInteractive')",
                "$start.ArgumentList.Add('-Command')",
                "$start.ArgumentList.Add('[Console]::Out.WriteLine(''descendant-ready''); " +
                "Start-Sleep -Seconds 30')",
                "$child = [Diagnostics.Process]::Start($start)",
                "$child.Dispose()");
            arguments =
            [
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                parentScript,
            ];
        }
        else
        {
            executable = "/bin/sh";
            arguments =
            [
                "-c",
                "/bin/sh -c 'printf \"descendant-ready\\n\"; sleep 30' &",
            ];
        }

        var stopwatch = System.Diagnostics.Stopwatch.StartNew();
        var exception = Record.Exception(
            () => RepositoryEvidenceTestSupport.RunProcess(
                SourceRepositoryRoot(),
                executable,
                arguments,
                standardInput: null,
                TimeSpan.FromSeconds(2)));

        Assert.IsType<TimeoutException>(exception);
        Assert.True(
            stopwatch.Elapsed < TimeSpan.FromSeconds(8),
            $"Descendant-held pipe cleanup took {stopwatch.Elapsed}.");
    }

    /// <summary>
    /// Short-lived real processes may exit between <see cref="System.Diagnostics.Process.Start()"/>
    /// and Windows job assignment without turning a successful command into a harness failure.
    /// </summary>
    [Fact]
    public void ProcessRunner_RepeatedQuickProcessesDoNotRaceJobAttachment()
    {
        for (var attempt = 0; attempt < 128; attempt++)
        {
            var executable = OperatingSystem.IsWindows()
                ? "git"
                : "/usr/bin/true";
            IReadOnlyList<string> arguments = OperatingSystem.IsWindows()
                ? ["rev-parse", "--is-inside-work-tree"]
                : [];
            var result = RepositoryEvidenceTestSupport.RunProcess(
                SourceRepositoryRoot(),
                executable,
                arguments,
                standardInput: null,
                TimeSpan.FromSeconds(2));

            Assert.Equal(0, result.ExitCode);
            if (OperatingSystem.IsWindows())
            {
                Assert.Equal(
                    "true",
                    System.Text.Encoding.UTF8.GetString(result.StandardOutput).Trim());
            }
            else
            {
                Assert.Empty(result.StandardOutput);
            }
        }
    }

    private static string SourceRepositoryRoot()
    {
        var metadata = typeof(BugTriage139FourteenthHarnessTests).Assembly
            .GetCustomAttributes<AssemblyMetadataAttribute>()
            .Single(
                attribute => string.Equals(
                    attribute.Key,
                    "McpRepositoryRoot",
                    StringComparison.Ordinal));
        return Path.GetFullPath(
            metadata.Value ??
            throw new InvalidOperationException("Build repository-root metadata is empty."));
    }
}
using System.Reflection;
using McpServer.Support.Mcp.Tests.Infrastructure;

namespace McpServer.Support.Mcp.Tests.Documentation;

/// <summary>
/// TEST-MCP-USECASE-019: Fifteenth-review consumer and deterministic-build contract tests.
/// </summary>
[Collection(RepositoryRootProcessStateCollection.Name)]
public sealed class BugTriage139FifteenthHarnessTests
{

    /// <summary>
    /// TEST-MCP-USECASE-019-AC005: Deterministic builds must retain an explicit checkout anchor and
    /// copy Agent Help fixtures beside the external test assembly without an environment override.
    /// </summary>
    [Fact]
    public void DeterministicBuild_EmbedsRepositoryRootAndCopiesAgentHelpFixtures()
    {
        var metadata = typeof(BugTriage139FifteenthHarnessTests).Assembly
            .GetCustomAttributes<AssemblyMetadataAttribute>()
            .SingleOrDefault(attribute =>
                string.Equals(
                    attribute.Key,
                    "McpRepositoryRoot",
                    StringComparison.Ordinal));
        Assert.NotNull(metadata);
        Assert.False(string.IsNullOrWhiteSpace(metadata!.Value));
        Assert.True(
            File.Exists(Path.Combine(metadata.Value!, "McpServer.sln")),
            metadata.Value);

        var fixture = Path.Combine(
            AppContext.BaseDirectory,
            "Fixtures",
            "AgentHelp",
            "bypass",
            "mcp-tool-failure-description.txt");
        Assert.True(File.Exists(fixture), fixture);
    }

    /// <summary>
    /// TEST-MCP-USECASE-020: The compiled test inventory must contain only the host-applicable
    /// native boundary tests, with an exact count rather than source-text substitutes.
    /// </summary>
    [Fact]
    public void PlatformNativeTests_CompiledInventoryMatchesHost()
    {
        var expected = OperatingSystem.IsWindows()
            ? new[]
            {
                "BugTriage139FifteenthSharedTests.ContainedRestoration_NestedDirectoriesRestoreContentsModeAndContainment",
                "BugTriage139FifteenthWindowsNativeTests.WorkspaceIdentity_NativeCancellationWindow_CompletesWithoutWorkerLeak",
                "BugTriage139FifteenthWindowsNativeTests.SqliteOpen_PlatformNativePreHandleWait_IsBoundedWithoutLeaks",
                "BugTriage139FifteenthWindowsNativeTests.SqliteOpen_KernelWaitThenIndependentDisposalFailure_PreservesExactException",
                "BugTriage139SixteenthIdentityWindowsTests.ResolveAsync_UnstoppableWindowsWorker_CompletesPubliclyAndRemainsObservable",
                "BugTriage139SixteenthIdentityWindowsTests.ResolveAsync_ResultWithheldUntilThreadExit_WorkerRemainsObservable",
                "BugTriage139SixteenthIdentityWindowsTests.ResolveAsync_RemoteUnc_IsRejectedBeforeNativeOpen",
                "BugTriage139SixteenthWindowsProcessTests.ProcessRunner_WindowsLaunchContract_UsesSuspendedCreation",
                "BugTriage139SixteenthWindowsProcessTests.ProcessRunner_AssignmentWindow_KeepsImmediateHelperSuspended",
                "BugTriage139SixteenthWindowsProcessTests.ProcessRunner_ImmediateNativeDescendant_IsKilledWithinBound",
            }
            : OperatingSystem.IsLinux()
                ? new[]
                {
                    "BugTriage139FifteenthSharedTests.ContainedRestoration_NestedDirectoriesRestoreContentsModeAndContainment",
                    "BugTriage139FifteenthLinuxNativeTests.WorkspaceIdentity_NativeCancellationWindow_CompletesWithoutWorkerLeak",
                    "BugTriage139FifteenthLinuxNativeTests.SqliteOpen_PlatformNativePreHandleWait_IsBoundedWithoutLeaks",
                    "BugTriage139FifteenthLinuxNativeTests.SqliteOpen_KernelWaitThenIndependentDisposalFailure_PreservesExactException",
                    "RequirementsFourteenthLinuxNativeTests.OpenFileForRead_LinuxFifoWithoutWriter_IsRejectedWithinBound",
                    "BugTriage139SixteenthLinuxTests.WorkspaceIdentity_SafeSymlinkIntoFuse_IsRejectedByAtomicNoCrossDeviceResolver",
                    "BugTriage139SixteenthLinuxTests.WorkspaceIdentity_AliasReplacement_IsRejectedByAtomicNoCrossDeviceResolver",
                    "BugTriage139SixteenthLinuxTests.SqliteOpen_SafeSymlinkIntoFuse_IsRejectedBeforeWorker",
                    "BugTriage139SixteenthLinuxTests.SqliteOpen_AliasReplacementBeforePhysicalResolution_IsRejected",
                    "BugTriage139SixteenthLinuxTests.SqliteOpen_AliasReplacementAtNativeOpen_IsAtomicallyRejected",
                    "BugTriage139SixteenthLinuxTests.WorkspaceIdentity_UnstoppableUnixHelper_RemainsObservableAfterPublicTimeout",
                    "BugTriage139SixteenthLinuxTests.SqlitePinnedDataSource_SupportsTransactionsAndReopen",
                }
                : new[]
                {
                    "BugTriage139FifteenthSharedTests.ContainedRestoration_NestedDirectoriesRestoreContentsModeAndContainment",
                };
        var governedTypes = new HashSet<string>(
            StringComparer.Ordinal)
        {
            "BugTriage139FifteenthSharedTests",
            "BugTriage139FifteenthWindowsNativeTests",
            "BugTriage139FifteenthLinuxNativeTests",
            "RequirementsFourteenthLinuxNativeTests",
            "BugTriage139SixteenthIdentityWindowsTests",
            "BugTriage139SixteenthLinuxTests",
            "BugTriage139SixteenthWindowsProcessTests",
        };
        var actual = typeof(BugTriage139FifteenthHarnessTests)
            .Assembly
            .GetTypes()
            .Where(type => governedTypes.Contains(type.Name))
            .SelectMany(type => type
                .GetMethods(BindingFlags.Instance | BindingFlags.Public)
                .Where(method => method.GetCustomAttribute<FactAttribute>() is not null)
                .Select(method => $"{type.Name}.{method.Name}"))
            .OrderBy(name => name, StringComparer.Ordinal)
            .ToArray();

        Assert.Equal(
            expected.OrderBy(name => name, StringComparer.Ordinal),
            actual);
    }
}
